CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `analyze_combined`  AS SELECT `lg`.`id` AS `id`, `lg`.`ue_id` AS `ue_id`, `lg`.`id_mtr_rueckkopplung_datenmaske` AS `id_mtr_rueckkopplung_datenmaske`, `lg`.`teilnehmer_id` AS `teilnehmer_id`, `lg`.`x_kognition` AS `x_kognition`, `lg`.`x_sozial` AS `x_sozial`, `lg`.`x_affektiv` AS `x_affektiv`, `lg`.`x_motivation` AS `x_motivation`, `lg`.`x_methodik` AS `x_methodik`, `lg`.`x_performanz` AS `x_performanz`, `lg`.`x_regulation` AS `x_regulation`, `lg`.`sum_kognition` AS `sum_kognition`, `lg`.`sum_sozial` AS `sum_sozial`, `lg`.`sum_affektiv` AS `sum_affektiv`, `lg`.`sum_motivation` AS `sum_motivation`, `lg`.`sum_methodik` AS `sum_methodik`, `lg`.`sum_performanz` AS `sum_performanz`, `lg`.`sum_regulation` AS `sum_regulation`, `lg`.`h_kognition` AS `h_kognition`, `lg`.`h_sozial` AS `h_sozial`, `lg`.`h_affektiv` AS `h_affektiv`, `lg`.`h_motivation` AS `h_motivation`, `lg`.`h_methodik` AS `h_methodik`, `lg`.`h_performanz` AS `h_performanz`, `lg`.`h_regulation` AS `h_regulation`, `lg`.`token_anzahl` AS `token_anzahl`, `lg`.`funktionsklassen_anzahl_gesamt` AS `funktionsklassen_anzahl_gesamt`, `lg`.`dominante_dimension` AS `dominante_dimension`, `lg`.`dominante_dimension_wert` AS `dominante_dimension_wert`, `lg`.`polaritaet_gesamt` AS `polaritaet_gesamt`, `lg`.`d_semantisch` AS `d_semantisch`, `al`.`datum` AS `datum`, `al`.`lehrkraft_id` AS `lehrkraft_id`, `al`.`gruppe_id` AS `gruppe_id`, `al`.`satzanzahl` AS `satzanzahl`, `al`.`mean_kognition` AS `mean_kognition`, `al`.`var_kognition` AS `var_kognition`, `al`.`range_kognition` AS `range_kognition`, `al`.`mean_sozial` AS `mean_sozial`, `al`.`var_sozial` AS `var_sozial`, `al`.`range_sozial` AS `range_sozial`, `al`.`mean_affektiv` AS `mean_affektiv`, `al`.`var_affektiv` AS `var_affektiv`, `al`.`range_affektiv` AS `range_affektiv`, `al`.`mean_motivation` AS `mean_motivation`, `al`.`var_motivation` AS `var_motivation`, `al`.`range_motivation` AS `range_motivation`, `al`.`mean_methodik` AS `mean_methodik`, `al`.`var_methodik` AS `var_methodik`, `al`.`range_methodik` AS `range_methodik`, `al`.`mean_performanz` AS `mean_performanz`, `al`.`var_performanz` AS `var_performanz`, `al`.`range_performanz` AS `range_performanz`, `al`.`mean_regulation` AS `mean_regulation`, `al`.`var_regulation` AS `var_regulation`, `al`.`range_regulation` AS `range_regulation`, `al`.`semantische_breite` AS `semantische_breite`, `al`.`d_semantisch_mean` AS `d_semantisch_mean`, `al`.`d_semantisch_std` AS `d_semantisch_std`, `al`.`polaritaet_index` AS `polaritaet_index`, `al`.`dominanz_breite` AS `dominanz_breite` FROM (`analyze_lehrkraftdaten` `al` join `frzk_semantische_dichte_lehrer_gesamt` `lg` on(`al`.`id_mtr_rueckkopplung_datenmaske` = `lg`.`id_mtr_rueckkopplung_datenmaske`)) ;

