INSERT INTO `frzk_funktionsklasse` (`id`, `name`, `beschreibung`, `literaturquelle`) VALUES
(0, 'funktional', 'Funktionales Wort ohne semantische Bewertungswirkung', 'Systemische FRZK-Definition: Stopwort-Kategorie ohne Einfluss auf semantische Dichte.'),
(1, 'performanzsteigerung', 'Leistungszuwachs und Kompetenzentwicklung', 'Hattie, J. (2009). Visible Learning: A Synthesis of Over 800 Meta-Analyses Relating to Achievement. London: Routledge; Helmke, A. (2009). Unterrichtsqualität und Lehrerprofessionalität. Seelze: Klett.'),
(2, 'performanzdefizit', 'Leistungsrückgang oder Nichterreichen von Zielen', 'Hattie, J. (2009). Visible Learning. London: Routledge.'),
(3, 'metakognitive_regulation', 'Selbstreflexion, Überprüfung, Strategieanpassung', 'Flavell, J. H. (1979). Metacognition and cognitive monitoring. American Psychologist, 34(10), 906–911; Zimmerman, B. J. (2000). Attaining self-regulation. In: Handbook of Self-Regulation. San Diego: Academic Press.'),
(4, 'kognitive_aktivierung', 'Vertieftes Verstehen, Durchdringen, Anwenden', 'Helmke, A. (2009). Unterrichtsqualität und Lehrerprofessionalität. Seelze: Klett.'),
(5, 'intrinsische_motivation', 'Interesse, Engagement, freiwillige Beteiligung', 'Deci, E. L., & Ryan, R. M. (1985). Intrinsic Motivation and Self-Determination in Human Behavior. New York: Plenum.'),
(6, 'extrinsische_motivation', 'Leistungsorientierung, Zielerreichung unter Vorgabe', 'Deci, E. L., & Ryan, R. M. (1985). Intrinsic Motivation and Self-Determination in Human Behavior. New York: Plenum.'),
(7, 'methodische_kompetenz', 'Strategieanwendung, strukturiertes Vorgehen', 'Zimmerman, B. J. (2000). Self-regulated learning. In: Handbook of Self-Regulation. San Diego: Academic Press.'),
(8, 'aufmerksamkeitsregulation', 'Konzentration, Fokussierung', 'Helmke, A. (2009). Unterrichtsqualität und Lehrerprofessionalität. Seelze: Klett.'),
(9, 'sozial_interaktion', 'Kooperation, Beteiligung', 'Johnson, D. W., & Johnson, R. T. (2009). An Educational Psychology Success Story: Social Interdependence Theory and Cooperative Learning. Educational Researcher, 38(5), 365–379.'),
(10, 'neutral', 'Semantisch nicht eindeutig zuordenbar', 'FRZK-Systemdefinition (eigene theoretische Modellierung im Rahmen der Dissertation).'),
(11, 'kognitiv_erinnern', 'Reproduktion von Faktenwissen', 'Bloom, B. S. (1956). Taxonomy of Educational Objectives: Handbook I: Cognitive Domain. New York: Longmans.'),
(12, 'kognitiv_verstehen', 'Strukturierendes Erfassen und Einordnen', 'Bloom, B. S. (1956); Anderson, L. W., & Krathwohl, D. R. (2001). A Taxonomy for Learning, Teaching, and Assessing. New York: Longman.'),
(13, 'kognitiv_anwenden', 'Transfer in neue Kontexte', 'Anderson, L. W., & Krathwohl, D. R. (2001). A Taxonomy for Learning, Teaching, and Assessing. New York: Longman.'),
(14, 'kognitiv_analysieren', 'Strukturelles Zerlegen und Untersuchen', 'Anderson, L. W., & Krathwohl, D. R. (2001). A Taxonomy for Learning, Teaching, and Assessing. New York: Longman.'),
(15, 'kognitiv_evaluieren', 'Kritische Beurteilung und Bewertung', 'Anderson, L. W., & Krathwohl, D. R. (2001). A Taxonomy for Learning, Teaching, and Assessing. New York: Longman.'),
(16, 'kognitiv_erschaffen', 'Kreatives Erzeugen neuer Strukturen', 'Anderson, L. W., & Krathwohl, D. R. (2001). A Taxonomy for Learning, Teaching, and Assessing. New York: Longman.'),
(17, 'affektiv_motivation', 'Haltungs- und Engagementdimension', 'Deci, E. L., & Ryan, R. M. (1985); Pekrun, R. (2006). The Control-Value Theory of Achievement Emotions. Educational Psychology Review, 18(4), 315–341.'),
(18, 'kommunikativ_interaktion', 'Kooperative und diskursive Interaktion', 'Johnson, D. W., & Johnson, R. T. (2009). Social Interdependence Theory.'),
