INSERT INTO `mtr_rueckkopplung_datenmaske` (`id`, `gruppe_id`, `teilnehmer_id`, `fach`, `datum`, `thema`, `bemerkung`, `wochentag`, `day_number`, `lehrkraft_id`) VALUES
(203, 2, 13, 'MAT', '2025-10-07', 'Weitere Themen: MatheOlymp', 'kann meistens der Aufgabenstellung entsprechend eine Antwort formulieren | hat zuletzt erkennbar von der individuellen Unterstützung in der Nachhilfe profitiert | kann sich weniger gut auf eine Aufgabe konzentrieren, wenn diese als schwierig empfunden wird | reagiert zögerlich auf Aufgaben, die vom bisherigen Aufgabenmuster abweichen | geht strukturiert an Aufgaben heran', 2, 1, 1),
(204, 0, 13, 'MAT', '2025-09-29', NULL, '', 1, 0, 2),
(205, 4, 13, 'MAT', '2025-09-24', 'Weitere Themen: negZ/ZStr', 'versteht die Grundlagen des aktuellen Themas größtenteils | hat zuletzt erkennbar von der individuellen Unterstützung in der Nachhilfe profitiert | versucht sich oftmals erneut an Aufgaben, mit denen es kurz zuvor Probleme gab | zeigt meistens Engagement bei der Vorbereitung auf die Nachhilfestunden | kann Aufmerksamkeit während des Lernens nur kurz aufrechterhalten', 3, 2, 1),
(206, 0, 13, 'MAT', '2025-09-22', 'Weitere Themen: KorrLK', 'versteht die Grundlagen des aktuellen Themas größtenteils | wendet die in der Nachhilfe gelernten Strategien meistens auch außerhalb der Nachhilfestunden an | ist wenig interessiert daran, neue Themen zu erkunden und zu lernen | zeigt meistens Engagement bei der Vorbereitung auf die Nachhilfestunden | Fähigkeit zum kreativen Denken ist wenig ausgeprägt', 1, 0, 1),
(207, 4, 13, 'MAT', '2025-09-10', 'Geometrie: AufgLB', 'fühlt sich eher unsicher bei der Anwendung des Gelernten in neuen Kontexten | Einstellung zum Lernen hat sich in letzter Zeit geringfügig verbessert | kann den eigenen Lösungsweg häufig nachvollziehbar schriftlich präsentieren | vertraut nur selten den eigenen Fähigkeiten | setzt Prioritäten bei Lernaufgaben wenig sinnvoll', 3, 2, 1),
(208, 4, 13, 'MAT', '2025-09-03', 'Dezimalzahlen: GRA', 'konnte Wissen in der heutigen Stunde teilweise erweitern | konnte in den vergangenen Wochen elementare neue Lernstrategien durch die Nachhilfe entwickeln | eher zurückhaltend gegenüber neuen Strategien oder Herangehensweisen beim Lernen, besonders nach Misserfolgen | schlägt gelegentlich sinnvolle Übungen oder Themen vor, an denen er arbeiten möchte | kann eigene Ideen erfolgreich umsetzen', 3, 2, 1),
(209, 4, 13, 'MAT', '2025-08-27', 'Grundrechenarten: schrftlMul', 'kann erlerntes Wissen weitgehend in eigenen Worten wiedergeben | Vorbereitung auf anstehende Tests hat sich etwas verbessert | nutzt nur vereinzelt Fragen, um eigenes Verständnis zu vertiefen | kommt nur vereinzelt aus eigener Motivation zur Nachhilfe | muss regelmäßig an formale Vorgehensweisen erinnert werden', 3, 2, 1),
(210, 0, 13, 'MAT', '2025-08-25', 'Weitere Themen: Dezimalzahlen und Kreise', 'erinnert sich gut an den zuvor behandelten Stoff | hat in letzter Zeit ein geringfügig besseres Verständnis für die Anforderungen der Lehrkraft in der Schule entwickelt | teilt sich die eigene Lernzeit angemessen ein | versucht sich oftmals erneut an Aufgaben, mit denen es kurz zuvor Probleme gab | zeigt nur hin und wieder Engagement bei der Vorbereitung auf die Nachhilfestunden | Wir haben Sekante und Tangente wiederholt. Anschließend haben wir Brüche in Dezimalzahlen umgewandelt. Mit anfänglicher Erklärung klappte dies gut.', 1, 0, 12),
(211, 4, 13, 'MAT', '2025-06-25', NULL, '', 3, 2, 2),
