INSERT INTO `mtr_rueckkopplung_datenmaske` (`id`, `gruppe_id`, `teilnehmer_id`, `fach`, `datum`, `thema`, `bemerkung`, `wochentag`, `day_number`, `lehrkraft_id`) VALUES
(435, 0, 8, 'MAT', '2025-11-06', 'Prüfungsvorbereitung: Vorbereitung auf eine Physik Arbeit', 'nutzt oft die gegebenen Tipps | konnte in den vergangenen Wochen einige neue Lernstrategien durch die Nachhilfe entwickeln | plant Lernaktivitäten häufig im Voraus | verhält sich offen, wenn die Lehrkraft über Rückschläge sprechen will (bzw. wenn er selbst darüber sprechen soll) | kann komplexe Informationen verständlich mit eigenen Worten erklären', 4, 3, 18),
(436, 2, 8, 'MAT', '2025-11-04', 'Algebra: TermeBinF', 'kann Gelerntes gut auf andere Fächer oder den Alltag übertragen | konnte in den vergangenen Wochen einige neue Lernstrategien durch die Nachhilfe entwickeln | schafft normalerweise alle Aufgaben in einer Klassenarbeit oder Leistungskontrollen in der dafür angesetzten Zeit | braucht ab und zu Ermutigung, nach Misserfolgen | bearbeitet Aufgaben erfolgreich ohne ständige Anleitung | nM SdP', 2, 1, 1),
(437, 0, 8, 'MAT', '2025-10-30', 'Weitere Themen: Selina wollte Physik eigenständig lernen', 'zeigt von Stunde zu Stunde meistens Fortschritte | Einfluss der Nachhilfe auf die gesamte schulische Entwicklung positiv | benötigt wenig Zeit, um nach einer Ablenkung die Arbeit wieder aufzunehmen | formuliert Fragen verständlich | hat geplante Zeit überwiegend sinnvoll genutzt', 4, 3, 18),
(438, 0, 8, 'MAT', '2025-10-23', 'Weitere Themen: Übungsaufgaben zum Lösen linearer Gleichungen', 'erkennt und korrigiert eigene Fehler meist selbstständig | Zuverlässigkeit bei den Hausaufgaben hat sich verbessert | ist offen für andere Lösungsansätze | Erfolge fördern die Motivation normalerweise | muss selten an formale Vorgehensweisen erinnert werden', 4, 3, 18),
(439, 2, 8, 'MAT', '2025-10-21', 'Geometrie: Körper', 'kann erlerntes Wissen bei unangekündigten Tests weniger zuverlässig abrufen | Notenentwicklung in den letzten Wochen unverändert | plant Lernaktivitäten häufig im Voraus | strebt oftmals danach, Aufgaben selbstständig, also ohne Hilfe, zu lösen | Wechsel zwischen verschiedenen Themen gelingt mit wenig Aufwand | nM Terme', 2, 1, 1),
(440, 0, 8, 'MAT', '2025-10-09', 'Stochastik (Wahrscheinlichkeitsrechnung): Wdh. von Wahrscheinlichkeitsrechnung', 'erinnert sich gut an den zuvor behandelten Stoff | Vorbereitung auf anstehende Tests hat sich verbessert | setzt Prioritäten bei Lernaufgaben sehr sinnvoll | kann sehr gut mit Druck umgehen, wenn Aufgaben sich ändern | kann komplexe Informationen verständlich mit eigenen Worten erklären', 4, 3, 18),
(441, 2, 8, 'MAT', '2025-10-07', 'Statistik: komplÜ', 'beherrscht die spezifischen Fachbegriffe zuverlässig | konnte in den vergangenen Wochen einige neue Lernstrategien durch die Nachhilfe entwickeln | kann Frustration aufgrund von Fehlern und Rückschlägen normalerweise vermeiden | strebt oftmals danach, Aufgaben selbstständig, also ohne Hilfe, zu lösen | kann erlerntes Wissen gut auf andere Aufgabenstellungen anwenden', 2, 1, 1),
(442, 0, 8, 'MAT', '2025-10-02', 'Prüfungsvorbereitung: Übungen zu linearen Gleichungen und Wdh. von Geometrie + Prozentrechnung', 'nutzt oft die gegebenen Tipps | konnte in den vergangenen Wochen einige neue Lernstrategien durch die Nachhilfe entwickeln | versucht sich oftmals erneut an Aufgaben, mit denen es kurz zuvor Probleme gab | setzt Prioritäten bei Lernaufgaben sinnvoll | vertraut oft den eigenen Fähigkeiten', 4, 3, 18),
(443, 2, 8, 'MAT', '2025-09-30', 'Kreis: Üb', 'hat sich in Bereichen, die zuvor als schwierig identifiziert wurden, deutlich verbessert | Vorbereitung auf anstehende Tests hat sich verbessert | verfolgt Lernziele stellenweise konsequent | kann zur Lösung eines komplexen Problems nur hin und wieder einzelne Zwischenschritte entwickeln | bereitet sich meistens auf Aufgaben vor, die wahrscheinlich in einer Klassenarbeit oder Leistungskontrolle vorkommen', 2, 1, 1),
(444, 2, 8, 'MAT', '2025-09-30', NULL, '', 2, 1, 2),
(445, 0, 8, 'MAT', '2025-09-25', 'Statistik: Übung zu kommender Leistungskontrolle', 'kann stets den Operatoren der Aufgabenstellung entsprechend eine Antwort formulieren | Prüfungsangst des Schülers hat sich verringert | kann komplexe Informationen verständlich mit eigenen Worten erklären | strebt oftmals danach, Aufgaben selbstständig, also ohne Hilfe, zu lösen | findet in der Regel einen angemessenen Ausgleich zwischen zügigem und genauem Arbeiten', 4, 3, 18),
(446, 2, 8, 'MAT', '2025-09-23', 'Stochastik (Wahrscheinlichkeitsrechnung): BaumD', 'kann erlerntes Wissen auch bei unangekündigten Tests zuverlässig abrufen | Nachhilfe hat in letzter Zeit merklich zur Organisationsfähigkeit beigetragen | setzt sich meistens Prioritäten bei Lernaufgaben | zeigt sich zielstrebig beim Erreichen von Lernzielen | kann gut mit Druck umgehen, wenn Aufgaben sich ändern', 2, 1, 1),
(447, 0, 8, 'MAT', '2025-09-18', 'Statistik: Modalwerte uzw.', 'kann erlerntes Wissen auch bei unangekündigten Tests zuverlässig abrufen | Selbstständigkeit hat sich in den letzten Wochen verbessert | teilt sich die eigene Lernzeit angemessen ein | braucht nie Ermutigung, nach Misserfolgen | kann komplexe Informationen sehr verständlich mit eigenen Worten erklären | Sie arbeitet bereits gut selbstäntigt und ist gut motiviert. Mit der Zeit wird sie bestimmt am Besten Ergebnissen erreichen.', 4, 3, 20),
(448, 2, 8, 'MAT', '2025-09-16', 'Statistik: Üb', 'ist überwiegend in der Lage, fremde Lösungen zu prüfen und enthaltene Fehler zu erkennen | Fähigkeit zum Verstehen und Analysieren komplexer Sachverhalte hat sich über die letzten Wochen verbessert | erkennt Fehler und Korrekturen während des Unterrichts weitgehend als Chance zum Lernen | Fähigkeit zum kreativen Denken ist ausgeprägt | setzt sich meistens Prioritäten bei Lernaufgaben', 2, 1, 1),
(449, 0, 8, 'MAT', '2025-09-11', 'Statistik: Übungsaufgaben zur Arbeit mit Statistiken', 'kann Gelerntes sehr gut auf andere Fächer oder den Alltag übertragen | hat in letzter Zeit ein besseres Verständnis für die Anforderungen der Lehrkraft in der Schule entwickelt | versteht vollkommen, dass es trotz (kleinen) Erfolgen wichtig sein kann, weiter zu üben | verhält sich offen, wenn die Lehrkraft über Rückschläge sprechen will (bzw. wenn er selbst darüber sprechen soll) | kann komplexe Informationen verständlich mit eigenen Worten erklären', 4, 3, 18),
(450, 2, 8, 'MAT', '2025-09-09', 'Weitere Themen: JahrAb', 'nutzt oft die gegebenen Tipps | wendet die in der Nachhilfe gelernten Strategien meistens auch außerhalb der Nachhilfestunden an | kann Wissen, das in den letzten Nachhilfestunden thematisiert wurde, meistens abrufen | antwortet auf spontane Fragen zufriedenstellend | offen für neue Strategien oder Herangehensweisen beim Lernen, besonders nach Misserfolgen | nM Statistik', 2, 1, 1),
(451, 0, 8, 'MAT', '2025-09-04', 'Stochastik (Wahrscheinlichkeitsrechnung): baumdiagr', 'versteht die Grundlagen des aktuellen Themas größtenteils | hat in letzter Zeit ein deutlich besseres Verständnis für die Anforderungen der Lehrkraft in der Schule entwickelt | kann zur Lösung eines komplexen Problems meistens einzelne Zwischenschritte entwickeln | arbeitet durchgängig in einem angemessenen Tempo | nutzt regelmäßig Fragen, um eigenes Verständnis zu vertiefen', 4, 3, 1),
(452, 2, 8, 'MAT', '2025-09-02', 'Stochastik (Wahrscheinlichkeitsrechnung): komplÜb', 'kann Gelerntes gut auf andere Fächer oder den Alltag übertragen | Nachhilfe hat in letzter Zeit merklich zur Organisationsfähigkeit beigetragen | verfolgt Lernziele konsequent | bittet aktiv um Feedback | kann sich zuverlässig an früher Gelerntes erinnern und es nutzen | prima', 2, 1, 1),
(453, 0, 8, 'MAT', '2025-08-28', 'Stochastik (Wahrscheinlichkeitsrechnung): Wahrscheinlich.rechnung f.test', 'ist überwiegend in der Lage, fremde Lösungen zu prüfen und enthaltene Fehler zu erkennen | wendet die in der Nachhilfe gelernten Strategien meistens auch außerhalb der Nachhilfestunden an | behält weitgehend den Überblick beim Lösen komplexer Aufgaben | kann geschickt zwischen Aufgaben wechseln, die unterschiedliche Lernbereiche abdecken | schafft normalerweise alle Aufgaben in einer Klassenarbeit oder Leistungskontrollen in der dafür angesetzten Zeit', 4, 3, 19),
(454, 2, 8, 'MAT', '2025-08-26', 'Stochastik (Wahrscheinlichkeitsrechnung): komplÜb', 'zeigt von Stunde zu Stunde meistens Fortschritte | Vorbereitung auf anstehende Tests hat sich verbessert | vertraut oft den eigenen Fähigkeiten | kann den eigenen Lösungsweg häufig nachvollziehbar mündlich präsentieren | erklärt komplexe Sachverhalte meistens in einer logischen Reihenfolge', 2, 1, 1),
(455, 0, 8, 'MAT', '2025-08-21', 'Stochastik (Wahrscheinlichkeitsrechnung): Hausaufgaben zu Stochastik/anschließende vermischte Übungen', 'Absprachen einhaltendbeteiligt sich / gute Mitarbeitfleißig / bemühtarbeitet selbstständigkonzentriertvorbereitetLernfortschritt erzieltBasiswissen vorhanden', 4, 3, 18),
